	(9, 'activity', 'Nouvelle activité créée', 'App\\Models\\Activity', 'created', 6, 'App\\Models\\User', 6, '{"attributes": {"id": 6, "titre": "Intégration de l\'API Twilio pour les rappels SMS", "status": "brouillon", "user_id": 6, "duration": "0.12", "end_time": "23:59:00", "created_at": "2026-08-02T22:53:12.000000Z", "project_id": 4, "start_time": "23:52:00", "updated_at": "2026-08-02T22:53:12.000000Z", "description": "Configuration du webhook et écriture du script d\'envoi automatique des SMS de rappel pour les rendez-vous de vaccination de la zone pilote.", "submitted_at": null, "activity_date": "2026-08-03T00:00:00.000000Z", "sub_project_id": 5, "activity_type_id": 1, "rejection_reason": null, "monthly_report_id": null}}', NULL, '2026-08-02 21:53:13', '2026-08-02 21:53:13'),
