	(37, 'monthly_report', 'Nouveau rapport mensuel créé', 'App\\Models\\MonthlyReport', 'created', 9, 'App\\Models\\User', 6, '{"attributes": {"status": "soumis", "objectives": "Si vous souhaitez que je traite, rédige ou analyse un texte, veuillez me fournir plus de détails. Vous pouvez par exemple :", "project_ids": "5", "report_date": "2026-08-11T00:00:00.000000Z", "achievements": "Si vous souhaitez que je traite, rédige ou analyse un texte, veuillez me fournir plus de détails. Vous pouvez par exemple :", "next_actions": "Si vous souhaitez que je traite, rédige ou analyse un texte, veuillez me fournir plus de détails. Vous pouvez par exemple :"}}', NULL, '2026-08-11 09:34:40', '2026-08-11 09:34:40'),
	(38, 'monthly_report', 'Nouveau rapport mensuel créé', 'App\\Models\\MonthlyReport', 'created', 10, 'App\\Models\\User', 6, '{"attributes": {"status": "brouillon", "objectives": "Coller le texte que vous souhaitez modifier, résumer ou traduire.Préciser le sujet d\'un texte que vous aimeriez que je rédige pour vous.Poser une question spécifique sur les types de textes ou la linguistique.", "project_ids": "", "report_date": "2026-08-11T00:00:00.000000Z", "achievements": "Coller le texte que vous souhaitez modifier, résumer ou traduire.Préciser le sujet d\'un texte que vous aimeriez que je rédige pour vous.Poser une question spécifique sur les types de textes ou la linguistique.", "next_actions": "Coller le texte que vous souhaitez modifier, résumer ou traduire.Préciser le sujet d\'un texte que vous aimeriez que je rédige pour vous.Poser une question spécifique sur les types de textes ou la linguistique."}}', NULL, '2026-08-11 09:36:09', '2026-08-11 09:36:09'),
	(41, 'report_validation', 'Validation de rapport effectuée', 'App\\Models\\ReportValidation', 'created', 10, 'App\\Models\\User', 5, '{"attributes": {"comment": "", "decision": "approuvé", "validated_at": "2026-08-11T11:03:57.000000Z", "validator_id": 5}}', NULL, '2026-08-11 10:03:57', '2026-08-11 10:03:57'),
