INSERT INTO `activity_types` (`id`, `name`, `description`, `color`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'Formation & Atelier', 'Sessions de renforcement des capacités, ateliers techniques, alphabétisation et autonomisation des bénéficiaires.', '#F59E0B', 1, '2026-07-13 01:39:09', '2026-07-13 08:41:20'),
	(2, 'Distribution d\'aide', 'Opérations humanitaires de terrain, logistique de secours et remises de kits (alimentaires, hygiène, abris).', '#EF4444', 1, '2026-07-13 08:37:12', '2026-07-13 08:37:12'),
	(3, 'Sensibilisation & Plaidoyer', 'Campagnes communautaires, interventions en milieu scolaire, mobilisation citoyenne et plaidoyer auprès des institutions.', '#3B82F6', 1, '2026-07-13 08:40:28', '2026-07-13 08:40:28'),
	(4, 'Consultation médicale', 'Soins de santé primaire, cliniques mobiles, campagnes de vaccination et suivi psychologique sur le terrain.', '#10B981', 1, '2026-07-13 08:42:21', '2026-07-13 08:42:21'),
	(5, 'Suivi & Évaluation (M&E)', 'Visites de contrôle, enquêtes d\'impact auprès des ménages, audits de projets et collecte de données terrain.', '#8B5CF6', 1, '2026-07-13 08:43:45', '2026-07-13 08:43:45'),
	(6, 'Réunion de coordination', 'Tables rondes avec les partenaires locaux, clusters humanitaires, comités de pilotage et réunions d\'équipe internes.', '#6B7280', 1, '2026-07-13 08:44:27', '2026-07-13 08:44:27'),
	(7, 'Levée de fonds & Événement', 'Galas de charité, webinaires donateurs, marathons solidaires et campagnes de collecte de financements.', '#EC4899', 1, '2026-07-13 08:45:04', '2026-07-13 08:45:04'),
	(8, 'Mission d\'évaluation des besoins', 'Diagnostics initiaux sur le terrain, cartographie des vulnérabilités avant le déploiement d\'un nouveau projet.', '#F97316', 1, '2026-07-13 08:45:39', '2026-07-13 08:45:39'),
	(9, 'Construction & Infrastructures', 'Chantiers communautaires, aménagement de points d\'eau (forages), réhabilitation d\'écoles ou de centres de santé.', '#78350F', 1, '2026-07-13 08:46:13', '2026-07-13 08:46:13'),
	(10, 'Reporting & Clôture', 'Rédaction des rapports techniques et financiers pour les bailleurs de fonds, et archivage des dossiers de projet.', '#14B8A6', 1, '2026-07-13 08:46:46', '2026-07-13 08:46:46');
