INSERT INTO `projects` (`id`, `code`, `name`, `description`, `manager_id`, `start_date`, `end_date`, `status`, `created_at`, `updated_at`) VALUES
	(1, 'PRJ-2026-MINCL', 'Migration Cloud de la Gestion Hospitalière.', 'Déploiement centralisé de la nouvelle application de gestion pour le Centre Hospitalier LUMIÈRE. Ce projet vise à interconnecter la réception-caisse, le laboratoire d\'analyses, la pharmacie et les salles de soins. L\'objectif est de sécuriser les données des patients, d\'automatiser le suivi des consultations et de générer des rapports de facturation mensuels fiables en tâche de fond pour la direction.', 1, '2026-07-15', '2026-12-31', 'active', '2026-07-11 17:58:48', '2026-07-11 18:02:38'),
	(2, 'PRJ-2026-001', 'Refonte du site E-commerce', 'Migration du site vers une architecture plus rapide et intégration d\'un nouveau système de paiement sécurisé.', 1, '2026-07-15', '2026-10-31', 'active', '2026-07-11 22:28:36', '2026-07-11 22:28:36'),
	(3, 'PRJ-2026-002', 'Déploiement CRM', 'Installation et configuration du logiciel Salesforce pour l\'équipe commerciale avec formation des utilisateurs.', 2, '2026-07-15', '2026-10-31', 'active', '2026-07-11 22:30:05', '2026-07-11 22:30:05'),
	(4, 'PROJ-SANTE-001', 'Modernisation de la Couverture Vaccinale', 'Déploiement d\'un système de suivi numérique des stocks de vaccins et automatisation des rappels par SMS pour les populations rurales.', 5, '2026-08-01', '2027-08-02', 'active', '2026-08-02 01:12:17', '2026-08-02 01:12:17'),
	(5, 'PROJ-SANTE-002', 'Reseau Alerte Precoce Malaria', 'Mise en place d\'une cartographie dynamique en temps réel pour détecter les foyers de transmission de la malaria et coordonner la distribution des moustiquaires.', 5, '2026-10-01', '2027-10-31', 'active', '2026-08-02 01:34:05', '2026-08-02 01:34:05');
